                    b.Property<bool>("FetchBasicOnly")
                        .HasColumnType("boolean")
                        .HasColumnName("fetch_basic_only");

                    b.PrimitiveCollection<string[]>("FetchLandTypes")
                        .HasColumnType("text[]")
                        .HasColumnName("fetch_land_types")
                        .HasComment("Fetchable land TYPES only (empty = any land, with fetch_basic_only for the Basic constraint); null = not a fetch. Color resolution happens per deck at query time, never at ingest.");

                    b.Property<bool>("IdentityBound")
                        .HasColumnType("boolean")
                        .HasColumnName("identity_bound")
                        .HasComment("True when every any-color ability of a five-color producer binds it to the commander's color identity or to lands the players control. Tier 1 clips the source's colors to the deck's color identity.");

                    b.Property<bool>("OpponentDependent")
                        .HasColumnType("boolean")
                        .HasColumnName("opponent_dependent")
                        .HasComment("Nonland sources only: true when every mana-producing ability and every fetch ability depends on another player or on combat. Tier 1 has no opponents, so it lists the source as excluded and does not count it.");

